-- Run this once in the Supabase dashboard: SQL Editor -> New query -> paste -> Run.
-- Safe to re-run.

create extension if not exists pgcrypto;

-- ---------- users (own auth: bcrypt + JWT, not Supabase Auth) ----------
create table if not exists public.users (
  id            uuid primary key default gen_random_uuid(),
  email         text not null unique,          -- stored lowercase by the API
  password_hash text not null,
  name          text not null,
  created_at    timestamptz not null default now()
);

-- ---------- reports (id is generated by the MOBILE APP = idempotency key) ----------
create table if not exists public.reports (
  id           uuid primary key,
  user_id      uuid not null references public.users (id) on delete cascade,
  description  text not null check (length(btrim(description)) > 0),
  status       text not null default 'pending' check (status in ('pending', 'committed')),
  created_at   timestamptz not null default now(),
  committed_at timestamptz
);

create index if not exists reports_user_committed_idx
  on public.reports (user_id, committed_at desc)
  where status = 'committed';

-- ---------- report_images (id also generated by the app) ----------
create table if not exists public.report_images (
  id           uuid primary key,
  report_id    uuid not null references public.reports (id) on delete cascade,
  position     int  not null check (position between 0 and 4),
  storage_path text,                            -- null until the bytes have arrived
  size_bytes   int  check (size_bytes is null or size_bytes <= 5242880),
  uploaded_at  timestamptz
);

create index if not exists report_images_report_idx on public.report_images (report_id, position);

-- ---------- row level security ----------
-- The API talks to Supabase with the service-role key (bypasses RLS) and enforces ownership itself.
-- Enabling RLS with no policies means the public anon key can read/write NOTHING.
alter table public.users         enable row level security;
alter table public.reports       enable row level security;
alter table public.report_images enable row level security;

-- ---------- private storage bucket ----------
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('report-images', 'report-images', false, 5242880, array['image/jpeg'])
on conflict (id) do update
  set public = false,
      file_size_limit = 5242880,
      allowed_mime_types = array['image/jpeg'];
